from __future__ import annotations
import inspect
import logging
from contextlib import contextmanager

try:
    from robot.running import EXECUTION_CONTEXTS
except ImportError:
    class EXECUTION_CONTEXTS:  # type: ignore[no-redef]
        current = None

ROBOT_RUNNING = EXECUTION_CONTEXTS.current is not None

__all__ = ["log_radar"]


@contextmanager
def _robot_log_level_none():
    # There's also BuiltIn().set_log_level() which could be used,
    # but it requires `robotframework` dependency. Plus it adds log entries
    # such as
    #
    # <msg time="..." level="DEBUG">Log level changed from NONE to TRACE.</msg>
    #
    # when restoring the original log level.
    ctx = EXECUTION_CONTEXTS.current
    old_level = ctx.output.set_log_level("NONE")
    try:
        yield
    finally:
        ctx.output.set_log_level(old_level)


def log_radar(message: str, **kwargs) -> None:
    """
    Log for the Impact Radar.

    The radar data must be provided as keyword arguments. For example:

        log_radar(
            f"Sending command: {command}",
            command=command,
            connection=self.address,
            proxies=self.proxies,
        )
    """
    if not ROBOT_RUNNING:
        return

    radar = kwargs
    extra = {"radar": radar}

    module_name, function_name, line_number = _get_callers_details()
    if "module" not in kwargs:
        radar["module"] = module_name
    radar["function"] = function_name
    radar["lineno"] = line_number

    # with _robot_log_level_none():
    logging.radar(message, extra=extra)  # type: ignore[attr-defined]


def _set_up_radar_log_level():
    level_name = "RADAR"
    level_num = 1

    method_name = level_name.lower()

    def log_radar_to_root(msg, *args, **kwargs):
        logging.log(level_num, msg, *args, **kwargs)

    logging.addLevelName(level_num, level_name)
    setattr(logging, level_name, level_num)
    setattr(logging, method_name, log_radar_to_root)


def _get_callers_details() -> tuple[str | None, str | None, str | None]:
    try:
        prev_frame = inspect.currentframe().f_back.f_back
    except AttributeError:
        module_name = r"¯\_(ツ)_/¯"
        function_name = line_number = None
    else:
        module = inspect.getmodule(prev_frame)
        module_name = f"{module.__name__}" if module else None
        (
            filename,
            line_number,
            function_name,
            lines,
            index,
        ) = inspect.getframeinfo(prev_frame)

    return module_name, function_name, line_number


if not hasattr(logging, "radar"):
    _set_up_radar_log_level()
